package cli

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// These use the public root command with a durable episode fixture. They pin
// the packet users receive, rather than the ranking helpers that build it.
func TestBriefOutputRootJSONAndTextContracts(t *testing.T) {
	opts, repoDir, _ := commandRegressionFixture(t)
	files := map[string]string{
		"providers/agentic-decider.ts":           "function callProvider() {\nconst metadata = { agentic_decision: { step: 1 } };\nreturn String(metadata);\n}\n",
		"packages/automation/agentic-decider.ts": "function executeAgenticPlan() {\nlet previousResponseId = null;\nconst perception: AgenticPerception = {\n previousResponseId: previousResponseId\n};\npreviousResponseId = decision.previousResponseId;\n}\n",
	}
	for rel, source := range files {
		path := filepath.Join(repoDir, rel)
		if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(path, []byte(source), 0o600); err != nil {
			t.Fatal(err)
		}
	}
	privatePath := filepath.Join(repoDir, ".git", "private-metadata.txt")
	if err := os.MkdirAll(filepath.Dir(privatePath), 0o700); err != nil {
		t.Fatal(err)
	}
	const privateCanary = "PRIVATE_BRIEF_METADATA_CANARY_739"
	if err := os.WriteFile(privatePath, []byte(privateCanary), 0o600); err != nil {
		t.Fatal(err)
	}
	task := "repair Responses API metadata and previous_response_id contract"
	out, err := execute(t, NewRootCommand(opts), "brief", task, "--json", "--limit", "8")
	if err != nil {
		t.Fatalf("brief json: %v\n%s", err, out)
	}
	var report map[string]any
	if err := json.Unmarshal([]byte(out), &report); err != nil {
		t.Fatalf("decode: %v\n%s", err, out)
	}
	if report["task"] != task || report["status"] == nil || report["guidance"] == nil {
		t.Fatalf("public report missing task/status/guidance: %#v", report)
	}
	public, _ := json.Marshal(report)
	for _, want := range []string{"Stringify the agentic_decision metadata step", "Delete the loop-scoped browser response-id accumulator"} {
		if !strings.Contains(string(public), want) {
			t.Fatalf("brief omitted public action %q: %s", want, public)
		}
	}
	if strings.Contains(out, privateCanary) {
		t.Fatalf("brief leaked fixture-private text: %s", out)
	}
	text, err := execute(t, NewRootCommand(opts), "brief", task, "--limit", "8")
	if err != nil || !strings.Contains(text, "task:") || !strings.Contains(text, task) {
		t.Fatalf("brief text: %v\n%s", err, text)
	}
}

func TestBriefOutputRejectsInvalidBudgetAtRoot(t *testing.T) {
	opts, _, _ := commandRegressionFixture(t)
	out, err := execute(t, NewRootCommand(opts), "brief", "metadata", "--limit", "0", "--json")
	if err == nil || !strings.Contains(err.Error(), "--limit must be greater than zero") {
		t.Fatalf("invalid budget: %v\n%s", err, out)
	}
}

