			}
			actions = append(actions, brainBriefAction{
				File: rel, Symbol: currentSymbol, Action: action,
				Evidence: fmt.Sprintf("current line %d: %s", i+1, truncateString(trimmed, 180)),
			})
		}
	}
	return actions
}

