+			Summary: "OVERLAY_CURRENT_CANARY preserve current history", Terms: []string{"overlay", "current", "canary"},
+		}}},
+	}
+	if err := saveHistoryShortTerm(fixture.brainDir, overlay); err != nil { t.Fatal(err) }
+	packet, err := execute(t, NewRootCommand(fixture.opts), "brief", "OVERLAY_CURRENT_CANARY", "--json", "--limit", "3")
+	if err != nil { t.Fatalf("overlay brief: %v\n%s", err, packet) }
+	var report brainBriefJSONReport
+	if err := json.Unmarshal([]byte(packet), &report); err != nil { t.Fatal(err) }
+	if len(report.History.Matches) == 0 || report.History.Matches[0].Path != rel || report.History.Matches[0].Line != 7 || !strings.Contains(report.History.Matches[0].Excerpt, "OVERLAY_CURRENT_CANARY") { t.Fatalf("current overlay absent or lost provenance: %#v", report.History.Matches) }
+}
+
+func TestBriefOutputPrivacyGuardFiltersIndexedHistory(t *testing.T) {
+	fixture := newBrainBriefOutputFixture(t)
+	manifest, err := loadBrainManifest(fixture.brainDir)
