+	index, err := loadBrainHistoryIndex(fixture.brainDir, manifest.Sources.History)
+	if err != nil { t.Fatal(err) }
+	var target historyRecord
+	for _, record := range index.Records { if strings.Contains(record.Path, "brief-evidence-1.jsonl") { target = record; break } }
+	if target.ID == "" || target.SessionID == "" { t.Fatalf("privacy fixture lacks indexed identity: %#v", target) }
+	if err := os.Remove(filepath.Join(fixture.brainDir, filepath.FromSlash(target.Path))); err != nil { t.Fatal(err) }
+	stones := loadSessionTombstones(fixture.brainDir)
+	stones.Excluded[target.SessionID] = sessionTombstone{At: fixture.opts.Now(), Reason: "brief regression"}
+	if err := saveSessionTombstones(fixture.brainDir, stones); err != nil { t.Fatal(err) }
+	packet, err := execute(t, NewRootCommand(fixture.opts), "brief", "ValidateToken public history provenance ordering budget evidence", "--json", "--limit", "8")
+	if err != nil { t.Fatalf("private brief: %v\n%s", err, packet) }
