func sortWorkspaceGraphSymbolRefs(refs []workspaceGraphSymbolRef) {
	sort.Slice(refs, func(i, j int) bool {
		if refs[i].RepoKey != refs[j].RepoKey {
			namespace := strings.TrimSpace(parts[1])
			if namespace == "" {
