	}
	seen := map[string]bool{}
	add := func(value string) {
		value = strings.Trim(strings.TrimSpace(value), ". /")
		if value != "" {
			seen[value] = true
		}
	}
	add(subpath)
	add(strings.ReplaceAll(subpath, "/", "."))
	parts := strings.FieldsFunc(subpath, func(r rune) bool { return r == '/' || r == '.' })
