			return lockedErr
		}
		if lockedErr = writeBrainPracticesFile(wsDir, pracs); lockedErr != nil {
			return lockedErr
		}
		return writeBrainTasksFile(wsDir, tasks)
	}); err != nil {
		return err
	}
	if err := bufferRetrievalCommandOutput(cmd, privacyPolicies, func() error {
