		out := cmd.OutOrStdout()
		if len(filtered) == 0 {
			fmt.Fprintf(out, "workspace %s: no cross-repo patterns (run `entire brain workspace patterns refresh %s`)\n", name, name)
			return nil
		}
		for _, v := range filtered {
			renderPatternView(out, v)
		}
		return nil
	})
