 290		if err := db.QueryRow(`PRAGMA quick_check`).Scan(&integrity); err != nil || integrity != "ok" {
 291			return nil, fmt.Errorf("%s: vector store %s failed integrity verification", memoryErrStateCorrupt, rel)
 292		}
 293		rows, err := db.Query(fmt.Sprintf(`SELECT record_id FROM history_ids LIMIT %d`, privacyVectorVerifyMaxRows+1))
 294		if err != nil {
 295			return nil, fmt.Errorf("%s: inspect vector IDs in %s: %w", memoryErrStateCorrupt, rel, err)
 296		}
 297		defer rows.Close()
 298		var findings []privacyVerifyFinding
 299		count := 0
 300		for rows.Next() {
 301			count++
 302			if count > privacyVectorVerifyMaxRows {
 303				return nil, fmt.Errorf("%s: vector store %s exceeds verification ceiling", memoryErrStateUnsafe, rel)
 304			}
 305			var id string
 306			if err := rows.Scan(&id); err != nil {
 307				return nil, fmt.Errorf("%s: inspect vector ID in %s: %w", memoryErrStateCorrupt, rel, err)
 308			}
 309			if _, current := wanted[id]; !current {
 310				findings = append(findings, privacyVerifyFinding{
 311					SessionID: findingSessionID,
 312					Artifact:  "vector_store",
 313					Detail:    rel + " contains record " + id + " outside the current tombstone-filtered history generation; rebuild vectors",
 314				})
