		t.Fatalf("missing target error = %v\n%s", err, out)
	}
	var cursors []string
	if walkErr := filepath.WalkDir(opts.Env.PluginDataDir, func(path string, entry os.DirEntry, walkErr error) error {
		if walkErr != nil {
