		t.Fatalf("inspect refused target writes: %v", walkErr)
	}
	if len(cursors) != 0 {
		t.Fatalf("refused target wrote watch cursors: %v", cursors)
	}
	assertMemoryWorkerLaunches(t, *launches, "", 0)
}

