	manifest, err := loadBrainManifest(brainDir)
	if err != nil || manifest.Sources == nil || manifest.Sources.Seed == nil {
		t.Fatalf("successful seed stage was not committed: manifest=%+v err=%v", manifest, err)
	}
}

