package cli

import "testing"

// TestCheckpointEntriesFromIDs_LimitKeepsTheNewest pins that --checkpoint-limit
// keeps the most recent checkpoints across BOTH ID formats.
//
// A ULID encodes a millisecond timestamp in its leading characters and is
// time-sortable; a legacy 12-hex ID is random throughout and carries no time.
// Sorting the mixed set as reversed strings ordered by byte value instead of
// recency — hex is lowercase, ULIDs are uppercase Crockford base32, so every
// hex ID beginning a-f sorted above every ULID. Under a limit that discarded
// the newest checkpoints (the ULIDs the git-refs backend mints) and kept the
// oldest ones from the pre-migration branch.
func TestCheckpointEntriesFromIDs_LimitKeepsTheNewest(t *testing.T) {
	t.Parallel()

	const legacyHex = "fedcba987654" // legacy 12-hex, no recoverable time
	const olderULID = "01AAAAAAAA4YW6J5M9GP655HZN"
	const newerULID = "01ZZZZZZZZ4YW6J5M9GP655HZN"

	for _, id := range []string{olderULID, newerULID} {
		if _, ok := checkpointULIDTime(id); !ok {
			t.Fatalf("fixture %q is not a recognized ULID checkpoint ID", id)
		}
	}

	ids := map[string]struct{}{
		legacyHex: {},
		olderULID: {},
		newerULID: {},
	}

	entries := checkpointEntriesFromIDs(ids, 2)
	if len(entries) != 2 {
		t.Fatalf("got %d entries, want 2", len(entries))
	}
	got := []string{entries[0].CheckpointID, entries[1].CheckpointID}
	want := []string{newerULID, olderULID}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("limit kept %v, want the two newest %v", got, want)
		}
	}
}

// TestCheckpointEntriesFromIDs_LegacyOnlyKeepsDescendingOrder keeps the previous
// behavior for a repo that has never minted a ULID: no time is recoverable from
// any of the IDs, so descending ID order stands.
func TestCheckpointEntriesFromIDs_LegacyOnlyKeepsDescendingOrder(t *testing.T) {
	t.Parallel()

	ids := map[string]struct{}{
		"aaaaaaaaaaaa": {},
		"ffffffffffff": {},
		"555555555555": {},
	}

	entries := checkpointEntriesFromIDs(ids, 0)
	want := []string{"ffffffffffff", "aaaaaaaaaaaa", "555555555555"}
	if len(entries) != len(want) {
		t.Fatalf("got %d entries, want %d", len(entries), len(want))
	}
	for i := range want {
		if entries[i].CheckpointID != want[i] {
			t.Fatalf("order %v, want %v", entries, want)
		}
	}
}
package cli

import (
	"context"
	"errors"
	"os"
	"path/filepath"
	"sort"
	"testing"
)

// Checkpoints do not necessarily sync to a remote named "origin". The CLI
// elects ONE remote to carry them — strategy_options.checkpoint_push_remote,
// then a remote a past push captured, then "origin", then the sole/first remote
// in .git/config order — and its read paths consult that elected remote first
// with "origin" behind it as a legacy tier
// (cmd/entire/cli/strategy/checkpoint_read_remotes.go). The export reader looked
// only at the local branch and origin's tracking ref, so a clone whose elected
// remote is named anything else had checkpoints the brain never saw.

const (
	remoteFork     = "fork"
	forkTrackingV1 = "refs/remotes/fork/entire/checkpoints/v1"
)

// syncRemoteRunner scripts a repository with the given remotes in .git/config
// order and one checkpoint tree per named tracking ref.
func syncRemoteRunner(remotes []string, trees map[string]string) *fakeCommandRunner {
	var config string
	for _, name := range remotes {
		config += "remote." + name + ".url https://example.test/" + name + ".git\n"
	}
	responses := map[string]fakeCommandResponse{
		fakeCommandKey("git", "config", "--local", "--get-regexp", `^remote\..*\.url$`): {stdout: config},
		fakeCommandKey("git", "rev-parse", "--git-common-dir"):                          {stdout: ".git\n"},
		fakeCommandKey("git", "ls-tree", "-r", "--name-only", v1MainRef):                {err: errors.New("no local checkpoint branch")},
		fakeCommandKey("git", "ls-tree", "-r", "--name-only", v1OriginRef):              {err: errors.New("no origin tracking ref")},
	}
	for ref, tree := range trees {
		responses[fakeCommandKey("git", "ls-tree", "-r", "--name-only", ref)] = fakeCommandResponse{stdout: tree}
	}
	return &fakeCommandRunner{responses: responses}
}

func sourceIDs(sources map[string]checkpointSnapshotSource) []string {
	ids := make([]string, 0, len(sources))
	for id := range sources {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	return ids
}

func writeRepoSettings(t *testing.T, repoDir, name, body string) {
	t.Helper()
	settingsDir := filepath.Join(repoDir, ".entire")
	if err := os.MkdirAll(settingsDir, 0o700); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(settingsDir, name), []byte(body), 0o600); err != nil {
		t.Fatal(err)
	}
}

// TestLoadAggregateCheckpointSources_ReadsConfiguredPushRemote pins the
// checkpoint_push_remote tier: the named remote's tracking ref is read.
func TestLoadAggregateCheckpointSources_ReadsConfiguredPushRemote(t *testing.T) {
	t.Parallel()

	repoDir := t.TempDir()
	writeRepoSettings(t, repoDir, "settings.local.json", `{"strategy_options":{"checkpoint_push_remote":"fork"}}`)
	runner := syncRemoteRunner([]string{"origin", remoteFork}, map[string]string{
		forkTrackingV1: "aa/aaaaaaaaaa/metadata.json\naa/aaaaaaaaaa/0/metadata.json\naa/aaaaaaaaaa/0/full.jsonl\n",
	})

	sources, _ := loadAggregateCheckpointSources(context.Background(), runner, repoDir, true, nil)

	if got := sourceIDs(sources); len(got) != 1 || got[0] != "aaaaaaaaaaaa" {
		t.Fatalf("discovered %v, want the checkpoint on the elected remote %q", got, remoteFork)
	}
	if sources["aaaaaaaaaaaa"].Ref != forkTrackingV1 {
		t.Errorf("checkpoint resolved to %s, want %s", sources["aaaaaaaaaaaa"].Ref, forkTrackingV1)
	}
}

// TestLoadAggregateCheckpointSources_ReadsSoleRemote pins the default tiers:
// with no origin and no setting, the one configured remote is elected.
func TestLoadAggregateCheckpointSources_ReadsSoleRemote(t *testing.T) {
	t.Parallel()

	runner := syncRemoteRunner([]string{"upstream"}, map[string]string{
		"refs/remotes/upstream/entire/checkpoints/v1": "bb/bbbbbbbbbb/metadata.json\nbb/bbbbbbbbbb/0/metadata.json\nbb/bbbbbbbbbb/0/full.jsonl\n",
	})

	sources, _ := loadAggregateCheckpointSources(context.Background(), runner, t.TempDir(), true, nil)

	if got := sourceIDs(sources); len(got) != 1 || got[0] != "bbbbbbbbbbbb" {
		t.Fatalf("discovered %v, want the checkpoint on the sole remote", got)
	}
}

// TestLoadAggregateCheckpointSources_KeepsOriginAsLegacyTier pins that origin
// stays in the read set behind a non-origin elected remote, which is where
// pre-election checkpoints live.
func TestLoadAggregateCheckpointSources_KeepsOriginAsLegacyTier(t *testing.T) {
	t.Parallel()

	repoDir := t.TempDir()
	writeRepoSettings(t, repoDir, "settings.local.json", `{"strategy_options":{"checkpoint_push_remote":"fork"}}`)
	runner := syncRemoteRunner([]string{"origin", remoteFork}, map[string]string{
		forkTrackingV1: "aa/aaaaaaaaaa/metadata.json\naa/aaaaaaaaaa/0/metadata.json\naa/aaaaaaaaaa/0/full.jsonl\n",
		v1OriginRef:    "bb/bbbbbbbbbb/metadata.json\nbb/bbbbbbbbbb/0/metadata.json\nbb/bbbbbbbbbb/0/full.jsonl\n",
	})

	sources, _ := loadAggregateCheckpointSources(context.Background(), runner, repoDir, true, nil)

	got := sourceIDs(sources)
	if len(got) != 2 || got[0] != "aaaaaaaaaaaa" || got[1] != "bbbbbbbbbbbb" {
		t.Fatalf("discovered %v, want both the elected remote's and origin's checkpoints", got)
	}
	if sources["aaaaaaaaaaaa"].Ref != forkTrackingV1 {
		t.Errorf("elected-remote checkpoint resolved to %s, want %s", sources["aaaaaaaaaaaa"].Ref, forkTrackingV1)
	}
	if sources["bbbbbbbbbbbb"].Ref != v1OriginRef {
		t.Errorf("legacy checkpoint resolved to %s, want %s", sources["bbbbbbbbbbbb"].Ref, v1OriginRef)
	}
}

// TestLoadAggregateCheckpointSources_UnreadableSettingsStillReadsOrigin pins the
// read-side fail-open: a broken election must not hide origin's checkpoints,
// which is the CLI's own rule for reads (writes fail closed, reads do not).
func TestLoadAggregateCheckpointSources_UnreadableSettingsStillReadsOrigin(t *testing.T) {
	t.Parallel()

	repoDir := t.TempDir()
	writeRepoSettings(t, repoDir, "settings.local.json", `{ this is not json`)
	runner := syncRemoteRunner([]string{"origin"}, map[string]string{
		v1OriginRef: "bb/bbbbbbbbbb/metadata.json\nbb/bbbbbbbbbb/0/metadata.json\nbb/bbbbbbbbbb/0/full.jsonl\n",
	})

	sources, _ := loadAggregateCheckpointSources(context.Background(), runner, repoDir, true, nil)

	if got := sourceIDs(sources); len(got) != 1 || got[0] != "bbbbbbbbbbbb" {
		t.Fatalf("discovered %v, want origin's checkpoint despite the unreadable settings", got)
	}
}

// TestLoadAggregateCheckpointSources_ReadsCapturedRemote pins the captured
// tier: a past push recorded the elected remote in the git common dir, and the
// export follows it without any setting.
func TestLoadAggregateCheckpointSources_ReadsCapturedRemote(t *testing.T) {
	t.Parallel()

	repoDir := t.TempDir()
	gitDir := filepath.Join(repoDir, ".git")
	if err := os.MkdirAll(gitDir, 0o700); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(gitDir, "entire-checkpoint-sync-remotes.json"), []byte(`{"remotes":["fork"]}`), 0o600); err != nil {
		t.Fatal(err)
	}
	// origin exists and would otherwise win the default tier.
	runner := syncRemoteRunner([]string{"origin", remoteFork}, map[string]string{
		forkTrackingV1: "aa/aaaaaaaaaa/metadata.json\naa/aaaaaaaaaa/0/metadata.json\naa/aaaaaaaaaa/0/full.jsonl\n",
	})

	sources, _ := loadAggregateCheckpointSources(context.Background(), runner, repoDir, true, nil)

	if got := sourceIDs(sources); len(got) != 1 || got[0] != "aaaaaaaaaaaa" {
		t.Fatalf("discovered %v, want the checkpoint on the captured remote %q", got, remoteFork)
	}
	if sources["aaaaaaaaaaaa"].Ref != forkTrackingV1 {
		t.Errorf("checkpoint resolved to %s, want %s", sources["aaaaaaaaaaaa"].Ref, forkTrackingV1)
	}
}

// TestLoadAggregateCheckpointSources_RejectsUnconfiguredPushRemote pins the
// fail-closed half of the election: checkpoint_push_remote naming a remote that
// does not exist elects nothing, and the read falls open to origin rather than
// fabricating a tracking ref.
func TestLoadAggregateCheckpointSources_RejectsUnconfiguredPushRemote(t *testing.T) {
	t.Parallel()

	repoDir := t.TempDir()
	writeRepoSettings(t, repoDir, "settings.local.json", `{"strategy_options":{"checkpoint_push_remote":"ghost"}}`)
	runner := syncRemoteRunner([]string{"origin"}, map[string]string{
		v1OriginRef: "bb/bbbbbbbbbb/metadata.json\nbb/bbbbbbbbbb/0/metadata.json\nbb/bbbbbbbbbb/0/full.jsonl\n",
	})

	sources, _ := loadAggregateCheckpointSources(context.Background(), runner, repoDir, true, nil)

	if got := sourceIDs(sources); len(got) != 1 || got[0] != "bbbbbbbbbbbb" {
		t.Fatalf("discovered %v, want origin's checkpoint", got)
	}
	for _, call := range runner.calls {
		for _, arg := range call.args {
			if arg == "refs/remotes/ghost/entire/checkpoints/v1" {
				t.Fatalf("read a tracking ref for a remote that is not configured: %+v", call)
			}
		}
	}
}
package cli

import (
	"context"
	"encoding/json"
	"errors"
	"io"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

type fakeCommandRunner struct {
	responses           map[string]fakeCommandResponse
	sequences           map[string][]fakeCommandResponse
	semanticSnapshotAny *fakeCommandResponse
	// fallback answers commands no explicit response covers, so a fixture can
	// script a WALKER (any revision range at any --max-count) instead of
	// pre-baking the one range a caller happened to ask for last. Explicit
	// responses still win, so a test can force a specific failure.
	fallback func(name string, args []string) (fakeCommandResponse, bool)
	calls    []fakeCommandCall
}

type fakeCommandResponse struct {
	stdout string
	stderr string
	err    error
}

type runOnlyCommandRunner struct {
	inner *fakeCommandRunner
}

func (r runOnlyCommandRunner) Run(ctx context.Context, dir, name string, args ...string) ([]byte, []byte, error) {
	return r.inner.Run(ctx, dir, name, args...)
}

type fakeCommandCall struct {
	dir         string
	name        string
	args        []string
	env         map[string]string
	hasDeadline bool
}

func (r *fakeCommandRunner) Run(ctx context.Context, dir, name string, args ...string) ([]byte, []byte, error) {
	return r.run(ctx, dir, nil, name, args...)
}

func (r *fakeCommandRunner) RunWithEnv(ctx context.Context, dir string, env map[string]string, name string, args ...string) ([]byte, []byte, error) {
	return r.run(ctx, dir, env, name, args...)
}

func (r *fakeCommandRunner) run(ctx context.Context, dir string, env map[string]string, name string, args ...string) ([]byte, []byte, error) {
	key := fakeCommandKey(name, args...)
	var hasDeadline bool
	if ctx != nil {
		_, hasDeadline = ctx.Deadline()
	}
	r.calls = append(r.calls, fakeCommandCall{
		dir:         dir,
		name:        name,
		args:        append([]string(nil), args...),
		env:         mapsClone(env),
		hasDeadline: hasDeadline,
	})

	if sequence, ok := r.sequences[key]; ok && len(sequence) > 0 {
		response := sequence[0]
		r.sequences[key] = sequence[1:]
		return []byte(response.stdout), []byte(response.stderr), response.err
	}

	response, ok := r.responses[key]
	if !ok {
		if r.semanticSnapshotAny != nil && fakeCommandIsSemanticSnapshotAnyRepo(name, args) {
			response := *r.semanticSnapshotAny
			return []byte(response.stdout), []byte(response.stderr), response.err
		}
		if key == fakeCommandKey("git", "symbolic-ref", "--quiet", "--short", "refs/remotes/origin/HEAD") {
			return []byte("origin/main\n"), nil, nil
		}
		// An unscripted fixture describes an ORDINARY machine, and an ordinary
		// machine has git. `git --version` reads no repository, so it cannot
		// fail for anything a fixture is modelling about a directory -- and the
		// diagnosis that separates "git is not installed" from "this is not a
		// repository" asks exactly this question. Leaving it unscripted made
		// every non-repository fixture also claim git was missing, which is how
		// four of them came to assert the wrong message. A fixture that really
		// does mean "no git on this machine" scripts this call to fail.
		if name == "git" && len(args) == 1 && args[0] == "--version" {
			return []byte("git version 2.48.1\n"), nil, nil
		}
		if r.fallback != nil {
			if response, handled := r.fallback(name, args); handled {
				return []byte(response.stdout), []byte(response.stderr), response.err
			}
		}
		if key == fakeCommandKey("entire", "graph", "version", "--json") {
			return []byte(`{"provider":"entire-graph","version":"test"}`), nil, nil
		}
		return nil, nil, errors.New("unexpected command: " + key)
	}
	return []byte(response.stdout), []byte(response.stderr), response.err
}

func mapsClone(values map[string]string) map[string]string {
	if values == nil {
		return nil
	}
	cloned := make(map[string]string, len(values))
	for key, value := range values {
		cloned[key] = value
	}
	return cloned
}

// Stream mirrors Run for tests, exposing the configured stdout as a streaming
// reader so the streaming semantic indexer exercises the same fixtures. The
// deadline is recorded identically to Run so timeout assertions still hold.
func (r *fakeCommandRunner) Stream(ctx context.Context, dir, name string, args ...string) (CommandStream, error) {
	key := fakeCommandKey(name, args...)
	var hasDeadline bool
	if ctx != nil {
		_, hasDeadline = ctx.Deadline()
	}
	r.calls = append(r.calls, fakeCommandCall{
		dir:         dir,
		name:        name,
		args:        append([]string(nil), args...),
		hasDeadline: hasDeadline,
	})

	response := r.lookupResponse(key, name, args)
	return &fakeCommandStream{
		stdout: strings.NewReader(response.stdout),
		stderr: []byte(response.stderr),
		err:    response.err,
	}, nil
}

func (r *fakeCommandRunner) lookupResponse(key, name string, args []string) fakeCommandResponse {
	if sequence, ok := r.sequences[key]; ok && len(sequence) > 0 {
		response := sequence[0]
		r.sequences[key] = sequence[1:]
		return response
	}
	if response, ok := r.responses[key]; ok {
		return response
	}
	if r.semanticSnapshotAny != nil && fakeCommandIsSemanticSnapshotAnyRepo(name, args) {
		return *r.semanticSnapshotAny
	}
	return fakeCommandResponse{err: errors.New("unexpected command: " + key)}
}

type fakeCommandStream struct {
	stdout *strings.Reader
	stderr []byte
	err    error
}

func (s *fakeCommandStream) Stdout() io.Reader     { return s.stdout }
func (s *fakeCommandStream) Wait() ([]byte, error) { return s.stderr, s.err }
func (s *fakeCommandStream) Close() error          { return nil }

func fakeCommandKey(name string, args ...string) string {
	return name + "\x00" + strings.Join(args, "\x00")
}

func fakeCommandIsSemanticSnapshotAnyRepo(name string, args []string) bool {
	if name != "entire" || len(args) < 6 {
		return false
	}
	if args[0] != "graph" || args[1] != "snapshot" || args[2] != "--repo" {
		return false
	}
	for _, arg := range args {
		if arg == "--ignore-file" {
			return false
		}
	}
	return true
}

