	t.Setenv("ENTIRE_BRAIN_NO_EGRESS", "1")
	const checkpointID = "01KVBJCWYA4YW6J5M9GP655HZN"
	repoDir := t.TempDir()
	settingsDir := filepath.Join(repoDir, ".entire")
