	} {
		t.Run(name, func(t *testing.T) {
			cmd := NewRootCommand(Options{Version: "test-version", Env: env, Runner: runner, Now: time.Now})
			out, err := execute(t, cmd, args...)
			if err == nil {
				t.Fatalf("search succeeded unexpectedly:\n%s", out)
			}
