	}
	after, err := os.ReadFile(snapshotPath)
	if err != nil {
		t.Fatalf("read snapshot after export: %v", err)
	}
	if !bytes.Equal(before, after) {
		t.Fatalf("snapshot was modified through hard-linked output")
	}
}

