	}
	if err := initializeSemanticSQLite(db); err != nil {
		_ = db.Close()
		t.Fatalf("init sqlite: %v", err)
	}
	tx, err := db.Begin()
	if err != nil {
		_ = db.Close()
		t.Fatalf("begin sqlite: %v", err)
	}
	if err := insertSemanticSymbol(tx, semanticRecord{
		RecordType:      "symbol",
		ID:              "other",
		Kind:            "function",
		Name:            "OtherSymbol",
		QualifiedName:   "other.Symbol",
		FilePath:        "internal/other.go",
