	tracePath := filepath.Join(t.TempDir(), "runtime-traces.ndjson")
	data := []byte(`{"from":"ValidateToken","to":"GET /tokens/{id}","type":"HANDLES_ROUTE"}
{"from":"ValidateToken","to":"missing target","type":"OBSERVED_CALL"}
