	if err != nil {
		_ = db.Close()
		t.Fatalf("begin sqlite: %v", err)
	}
	if err := insertSemanticSymbol(tx, semanticRecord{
		RecordType:      "symbol",
		ID:              "other",
		Kind:            "function",
		Name:            "OtherSymbol",
		QualifiedName:   "other.Symbol",
		FilePath:        "internal/other.go",
		StartLine:       1,
		EndLine:         2,
		Signature:       "func OtherSymbol()",
		Language:        "Go",
		StableIDVersion: "1",
	}); err != nil {
